from __future__ import annotations

from typing import Any, Callable

from .errors import ConflictError, NotFoundError, ValidationError
from .model import (
    RESOURCE_TYPES,
    ValidatedResource,
    criteria_match,
    fields_for,
    identifiers_of,
    parse_resource,
    parse_subscription,
    resolve_reference,
    search_match,
    validate_path_id,
)
from .store import Store

_CONTROL_PARAMETERS = ("_count", "_offset", "_sort")


class FhirVault:
    def __init__(self, database: str, clock: Callable[[], Any] | None = None):
        self.store = Store(database, clock)

    # ------------------------------------------------------------------ helpers

    def _idempotent(self, key: str | None, operation: str, action: Callable[[], dict[str, Any]]) -> dict[str, Any]:
        if not key:
            raise ValidationError("Idempotency-Key header is required")
        existing = self.store.connection.execute(
            "SELECT operation, response FROM idempotency WHERE key = ?", (key,)
        ).fetchone()
        if existing:
            if existing["operation"] != operation:
                raise ConflictError("idempotency key was already used for another operation")
            return self.store.decode(existing["response"])
        with self.store.transaction():
            response = action()
            self.store.connection.execute(
                "INSERT INTO idempotency(key, operation, response) VALUES (?, ?, ?)",
                (key, operation, self.store.encode(response)),
            )
        return response

    def _require(self, resource_type: str, resource_id: str) -> Any:
        if resource_type not in RESOURCE_TYPES:
            raise NotFoundError(f"resource type {resource_type} is not supported")
        row = self.store.connection.execute(
            "SELECT document, current_version, deleted, last_updated FROM resources WHERE type = ? AND id = ?",
            (resource_type, resource_id),
        ).fetchone()
        if row is None or row["deleted"]:
            raise NotFoundError(f"{resource_type}/{resource_id} was not found")
        return row

    def _write(self, validated: ValidatedResource, *, reject_existing: bool) -> dict[str, Any]:
        row = self.store.connection.execute(
            "SELECT current_version, deleted FROM resources WHERE type = ? AND id = ?",
            (validated.resource_type, validated.resource_id),
        ).fetchone()
        if row is not None and not row["deleted"] and reject_existing:
            raise ConflictError(f"{validated.resource_type}/{validated.resource_id} already exists")
        version = 1 if row is None else row["current_version"] + 1
        moment = self.store.now()
        document = self._compose(validated, version, moment)
        connection = self.store.connection
        connection.execute(
            "INSERT INTO resources(type, id, deleted, current_version, document, last_updated) "
            "VALUES (?, ?, 0, ?, ?, ?) "
            "ON CONFLICT(type, id) DO UPDATE SET deleted = 0, current_version = excluded.current_version, "
            "document = excluded.document, last_updated = excluded.last_updated",
            (validated.resource_type, validated.resource_id, version, self.store.encode(document), moment),
        )
        connection.execute(
            "INSERT INTO versions(type, id, version, document, recorded_at) VALUES (?, ?, ?, ?, ?)",
            (validated.resource_type, validated.resource_id, version, self.store.encode(document), moment),
        )
        self._record_events(validated.resource_type, validated.resource_id, "created" if version == 1 else "updated", version, document, moment)
        return document

    @staticmethod
    def _compose(validated: ValidatedResource, version: int, moment: str) -> dict[str, Any]:
        document: dict[str, Any] = {"resourceType": validated.resource_type}
        document.update(validated.document)
        document["id"] = validated.resource_id
        document["meta"] = {"versionId": str(version), "lastUpdated": moment}
        return document

    # ------------------------------------------------------------------ resources

    def create(self, resource_type: str, raw: Any, key: str | None = None) -> dict[str, Any]:
        if resource_type not in RESOURCE_TYPES:
            raise NotFoundError(f"resource type {resource_type} is not supported")
        validated = parse_resource(resource_type, raw)
        self._assert_references(validated)
        return self._idempotent(
            key,
            f"create:{resource_type}/{validated.resource_id}",
            lambda: self._write(validated, reject_existing=True),
        )

    def read(self, resource_type: str, resource_id: str) -> dict[str, Any]:
        validate_path_id(resource_id)
        row = self._require(resource_type, resource_id)
        return self.store.decode(row["document"])

    def update(self, resource_type: str, resource_id: str, raw: Any, key: str | None = None) -> dict[str, Any]:
        validate_path_id(resource_id)
        validated = parse_resource(resource_type, raw, expected_id=resource_id)
        self._assert_references(validated)
        return self._idempotent(
            key,
            f"update:{resource_type}/{resource_id}",
            lambda: self._write(validated, reject_existing=False),
        )

    def delete(self, resource_type: str, resource_id: str, key: str | None = None) -> dict[str, Any]:
        validate_path_id(resource_id)

        def apply() -> dict[str, Any]:
            row = self._require(resource_type, resource_id)
            version = row["current_version"] + 1
            moment = self.store.now()
            document = self.store.decode(row["document"])
            document["meta"] = {"versionId": str(version), "lastUpdated": moment}
            connection = self.store.connection
            connection.execute(
                "UPDATE resources SET deleted = 1, current_version = ?, document = ?, last_updated = ? "
                "WHERE type = ? AND id = ?",
                (version, self.store.encode(document), moment, resource_type, resource_id),
            )
            connection.execute(
                "INSERT INTO versions(type, id, version, document, recorded_at) VALUES (?, ?, ?, ?, ?)",
                (resource_type, resource_id, version, self.store.encode(document), moment),
            )
            self._record_events(resource_type, resource_id, "deleted", version, document, moment)
            return {"id": resource_id, "resourceType": resource_type, "deleted": True, "version": version, "lastUpdated": moment}

        return self._idempotent(key, f"delete:{resource_type}/{resource_id}", apply)

    def history(self, resource_type: str, resource_id: str) -> dict[str, Any]:
        validate_path_id(resource_id)
        if resource_type not in RESOURCE_TYPES:
            raise NotFoundError(f"resource type {resource_type} is not supported")
        head = self.store.connection.execute(
            "SELECT current_version, deleted FROM resources WHERE type = ? AND id = ?",
            (resource_type, resource_id),
        ).fetchone()
        if head is None:
            raise NotFoundError(f"{resource_type}/{resource_id} was not found")
        rows = self.store.connection.execute(
            "SELECT version, document, recorded_at FROM versions WHERE type = ? AND id = ? ORDER BY version",
            (resource_type, resource_id),
        ).fetchall()
        entries = []
        for row in rows:
            document = self.store.decode(row["document"])
            entries.append(
                {
                    "version": row["version"],
                    "recordedAt": row["recorded_at"],
                    "current": bool(row["version"] == head["current_version"] and not head["deleted"]),
                    "resource": document if not head["deleted"] or row["version"] != head["current_version"] else None,
                    "tombstone": bool(head["deleted"] and row["version"] == head["current_version"]),
                    "meta": {"versionId": str(row["version"]), "lastUpdated": row["recorded_at"]},
                }
            )
        return {"resourceType": resource_type, "id": resource_id, "deleted": bool(head["deleted"]), "entries": entries}

    def search(self, resource_type: str, parameters: dict[str, list[str]]) -> dict[str, Any]:
        if resource_type not in RESOURCE_TYPES:
            raise NotFoundError(f"resource type {resource_type} is not supported")
        unknown = set(parameters) - set(fields_for(resource_type)) - set(_CONTROL_PARAMETERS) - {"id"}
        if unknown:
            raise ValidationError(
                f"unknown search parameters: {', '.join(sorted(unknown))}; supported parameters are "
                f"{', '.join(sorted(set(fields_for(resource_type)) | {'id'} | set(_CONTROL_PARAMETERS)))}"
            )
        count, offset = self._paging(parameters)
        sort = parameters.get("_sort", ["_id"])[0]
        rows = self.store.connection.execute(
            "SELECT id, document FROM resources WHERE type = ? AND deleted = 0",
            (resource_type,),
        ).fetchall()
        matched: list[tuple[str, dict[str, Any]]] = []
        for row in rows:
            document = self.store.decode(row["document"])
            if "id" in parameters and row["id"] not in parameters["id"]:
                continue
            identifiers = identifiers_of(document)
            if not all(
                any(
                    search_match(resource_type, document, identifiers, field, value)
                    for value in values
                )
                for field, values in parameters.items()
                if field not in _CONTROL_PARAMETERS and field != "id"
            ):
                continue
            matched.append((row["id"], document))
        matched.sort(key=lambda item: item[0], reverse=sort == "-_id")
        total = len(matched)
        page = matched[offset:] if count is None else matched[offset : offset + count]
        return {
            "resourceType": resource_type,
            "total": total,
            "count": len(page),
            "offset": offset,
            "sort": sort,
            "parameters": {name: sorted(values) for name, values in sorted(parameters.items())},
            "entry": [{"resource": document} for _, document in page],
        }

    @staticmethod
    def _paging(parameters: dict[str, list[str]]) -> tuple[int | None, int]:
        count: int | None = None
        if "_count" in parameters:
            raw_count = parameters["_count"][-1]
            if not raw_count.isdigit() or int(raw_count) > 1000:
                raise ValidationError("_count must be an integer between 0 and 1000")
            count = int(raw_count)
        offset = 0
        if "_offset" in parameters:
            raw_offset = parameters["_offset"][-1]
            if not raw_offset.isdigit():
                raise ValidationError("_offset must be a non-negative integer")
            offset = int(raw_offset)
        if parameters.get("_sort", ["_id"])[0] not in ("_id", "-_id"):
            raise ValidationError("_sort must be _id or -_id")
        return count, offset

    # ------------------------------------------------------------------ subscriptions

    def create_subscription(self, raw: Any, key: str | None = None, payload_id: Any = None) -> dict[str, Any]:
        subscription_id, criteria, reason = parse_subscription(raw, payload_id)

        def apply() -> dict[str, Any]:
            moment = self.store.now()
            try:
                self.store.connection.execute(
                    "INSERT INTO subscriptions(id, criteria, reason, created_at) VALUES (?, ?, ?, ?)",
                    (subscription_id, self.store.encode(criteria), reason, moment),
                )
            except Exception as error:
                if "UNIQUE constraint" in str(error):
                    raise ConflictError(f"Subscription/{subscription_id} already exists") from error
                raise
            return {"subscription_id": subscription_id, "created_at": moment, "criteria": criteria, "reason": reason}

        return self._idempotent(key, f"create-subscription:{subscription_id}", apply)

    def events(self, subscription_id: str) -> dict[str, Any]:
        row = self.store.connection.execute(
            "SELECT id, criteria FROM subscriptions WHERE id = ?", (subscription_id,)
        ).fetchone()
        if row is None:
            raise NotFoundError(f"Subscription/{subscription_id} was not found")
        rows = self.store.connection.execute(
            "SELECT payload FROM events WHERE subscription_id = ? ORDER BY sequence", (subscription_id,)
        ).fetchall()
        return {
            "subscription_id": subscription_id,
            "criteria": self.store.decode(row["criteria"]),
            "total": len(rows),
            "events": [self.store.decode(stored["payload"]) for stored in rows],
        }

    def _record_events(
        self,
        resource_type: str,
        resource_id: str,
        event: str,
        version: int,
        document: dict[str, Any],
        moment: str,
    ) -> None:
        rows = self.store.connection.execute(
            "SELECT id, criteria FROM subscriptions ORDER BY id"
        ).fetchall()
        for row in rows:
            criteria = self.store.decode(row["criteria"])
            if not criteria_match(criteria, resource_type, document):
                continue
            sequence_row = self.store.connection.execute(
                "SELECT COALESCE(MAX(sequence), 0) + 1 AS sequence FROM events WHERE subscription_id = ?",
                (row["id"],),
            ).fetchone()
            payload = {
                "sequence": sequence_row["sequence"],
                "subscription_id": row["id"],
                "event": event,
                "resource": f"{resource_type}/{resource_id}",
                "version": version,
                "occurredAt": moment,
            }
            self.store.connection.execute(
                "INSERT INTO events(subscription_id, sequence, type, payload, occurred_at) VALUES (?, ?, ?, ?, ?)",
                (row["id"], payload["sequence"], event, self.store.encode(payload), moment),
            )

    # ------------------------------------------------------------------ references

    def _assert_references(self, validated: ValidatedResource) -> None:
        for field, reference in validated.references:
            resolve_reference(self.store.connection, validated.resource_type, field, reference)

from __future__ import annotations

import argparse
import json
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from typing import Any
from urllib.parse import parse_qs, unquote, urlsplit

from .errors import FhirVaultError, NotFoundError, ValidationError
from .service import FhirVault


def make_handler(service: FhirVault) -> type[BaseHTTPRequestHandler]:
    class Handler(BaseHTTPRequestHandler):
        protocol_version = "HTTP/1.1"

        def log_message(self, format: str, *args: Any) -> None:
            return

        def _json(self, status: int, value: Any) -> None:
            body = json.dumps(value, ensure_ascii=False, separators=(",", ":")).encode()
            self.send_response(status)
            self.send_header("Content-Type", "application/json; charset=utf-8")
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            self.wfile.write(body)

        def _body(self) -> Any:
            content_type = self.headers.get("Content-Type", "")
            if content_type.split(";", 1)[0].strip().lower() != "application/json":
                raise ValidationError("Content-Type must be application/json")
            try:
                length = int(self.headers.get("Content-Length", "0"))
                if length < 0 or length > 1_000_000:
                    raise ValueError
                return json.loads(self.rfile.read(length))
            except (ValueError, json.JSONDecodeError) as error:
                raise ValidationError("request body must be valid JSON") from error

        def _segments(self) -> tuple[list[str], dict[str, list[str]]]:
            split = urlsplit(self.path)
            parts = [unquote(part) for part in split.path.split("/") if part]
            return parts, parse_qs(split.query, keep_blank_values=True)

        def _dispatch(self) -> tuple[int, Any]:
            parts, query = self._segments()
            key = self.headers.get("Idempotency-Key")
            if self.command == "GET" and parts == ["health"]:
                return 200, {"status": "ok"}
            if parts and parts[0] == "fhir":
                return self._resource_routes(parts[1:], query, key)
            if parts[:1] == ["Subscription"]:
                if self.command == "POST" and len(parts) == 1:
                    return 201, service.create_subscription(self._body(), key)
                raise NotFoundError("route was not found")
            if parts[:1] == ["subscriptions"]:
                if self.command == "GET" and len(parts) == 3 and parts[2] == "events":
                    return 200, service.events(parts[1])
                raise NotFoundError("route was not found")
            raise NotFoundError("route was not found")

        def _resource_routes(self, parts: list[str], query: dict[str, list[str]], key: str | None) -> tuple[int, Any]:
            if not parts:
                raise NotFoundError("route was not found")
            resource_type = parts[0]
            if resource_type == "Subscription":
                if self.command == "POST" and len(parts) == 1:
                    return 201, service.create_subscription(self._body(), key)
                raise NotFoundError("route was not found")
            if len(parts) == 1:
                if self.command == "POST":
                    return 201, service.create(resource_type, self._body(), key)
                if self.command == "GET":
                    return 200, service.search(resource_type, query)
                raise NotFoundError("route was not found")
            if len(parts) == 2:
                resource_id = parts[1]
                if self.command == "GET":
                    return 200, service.read(resource_type, resource_id)
                if self.command == "PUT":
                    return 200, service.update(resource_type, resource_id, self._body(), key)
                if self.command == "DELETE":
                    return 200, service.delete(resource_type, resource_id, key)
                raise NotFoundError("route was not found")
            if len(parts) == 3 and parts[2] == "_history" and self.command == "GET":
                return 200, service.history(resource_type, parts[1])
            raise NotFoundError("route was not found")

        def _handle(self) -> None:
            try:
                status, response = self._dispatch()
                self._json(status, response)
            except FhirVaultError as error:
                self._json(error.status, {"error": {"code": error.code, "message": str(error)}})
            except Exception:
                self._json(500, {"error": {"code": "internal_error", "message": "internal server error"}})

        do_GET = _handle
        do_POST = _handle
        do_PUT = _handle
        do_DELETE = _handle

    return Handler


def main() -> None:
    parser = argparse.ArgumentParser(description="Run the FhirVault HTTP service")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", default=8080, type=int)
    parser.add_argument("--database", default="fhirvault.db")
    arguments = parser.parse_args()
    service = FhirVault(arguments.database)
    server = ThreadingHTTPServer((arguments.host, arguments.port), make_handler(service))
    print(f"FhirVault listening on http://{arguments.host}:{arguments.port}", flush=True)
    server.serve_forever()


if __name__ == "__main__":
    main()

class FhirVaultError(Exception):
    code = "internal_error"
    status = 500


class ValidationError(FhirVaultError):
    code = "validation_error"
    status = 400


class NotFoundError(FhirVaultError):
    code = "not_found"
    status = 404


class ConflictError(FhirVaultError):
    code = "conflict"
    status = 409

from __future__ import annotations

import json
import sqlite3
from contextlib import contextmanager
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Callable, Iterator


class Store:
    def __init__(self, path: str, clock: Callable[[], datetime] | None = None):
        if path != ":memory:":
            Path(path).parent.mkdir(parents=True, exist_ok=True)
        self.clock = clock or (lambda: datetime.now(timezone.utc))
        self.connection = sqlite3.connect(path, isolation_level=None, check_same_thread=False)
        self.connection.row_factory = sqlite3.Row
        self.connection.execute("PRAGMA journal_mode = WAL")
        self.connection.executescript(
            """
            CREATE TABLE IF NOT EXISTS resources (
              type TEXT NOT NULL,
              id TEXT NOT NULL,
              deleted INTEGER NOT NULL DEFAULT 0,
              current_version INTEGER NOT NULL,
              document TEXT NOT NULL,
              last_updated TEXT NOT NULL,
              PRIMARY KEY (type, id)
            );
            CREATE TABLE IF NOT EXISTS versions (
              type TEXT NOT NULL,
              id TEXT NOT NULL,
              version INTEGER NOT NULL,
              document TEXT NOT NULL,
              recorded_at TEXT NOT NULL,
              PRIMARY KEY (type, id, version)
            );
            CREATE TABLE IF NOT EXISTS subscriptions (
              id TEXT PRIMARY KEY,
              criteria TEXT NOT NULL,
              reason TEXT,
              created_at TEXT NOT NULL
            );
            CREATE TABLE IF NOT EXISTS events (
              subscription_id TEXT NOT NULL REFERENCES subscriptions(id),
              sequence INTEGER NOT NULL,
              type TEXT NOT NULL,
              payload TEXT NOT NULL,
              occurred_at TEXT NOT NULL,
              PRIMARY KEY (subscription_id, sequence)
            );
            CREATE TABLE IF NOT EXISTS idempotency (
              key TEXT PRIMARY KEY,
              operation TEXT NOT NULL,
              response TEXT NOT NULL
            );
            """
        )

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        self.connection.execute("BEGIN IMMEDIATE")
        try:
            yield self.connection
        except Exception:
            self.connection.execute("ROLLBACK")
            raise
        else:
            self.connection.execute("COMMIT")

    @staticmethod
    def encode(value: Any) -> str:
        return json.dumps(value, ensure_ascii=False, separators=(",", ":"), sort_keys=True)

    @staticmethod
    def decode(value: str) -> Any:
        return json.loads(value)

    def now(self) -> str:
        """Current instant as an RFC 3339 UTC timestamp with millisecond precision."""
        return self.clock().astimezone(timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")

        raise ValidationError(
            f"{where} must match {_ID_PATTERN.pattern} (letters, digits, dot, dash, underscore; at most 100 characters)"
        )
    return value


def validate_path_id(resource_id: str) -> str:
    return _identifier(resource_id, "resource id")


def _instant(value: Any, where: str) -> str:
    if not isinstance(value, str) or not _INSTANT_PATTERN.match(value):
        raise ValidationError(f"{where} must be an RFC 3339 instant such as 2026-01-05T09:00:00Z")
    return value


def _string(value: Any, where: str) -> str:
    if not isinstance(value, str) or not value or len(value) > 200:
        raise ValidationError(f"{where} must be a non-empty string of at most 200 characters")
    return value


def _validate(kind: str, value: Any, resource_type: str, field: str) -> Any:
    where = f"{resource_type}.{field}"
    if kind == "string":
        return _string(value, where)
    if kind == "boolean":
        if not isinstance(value, bool):
            raise ValidationError(f"{where} must be a boolean")
        return value
    if kind == "code":
        allowed = _CODES[(resource_type, field)]
        if not isinstance(value, str) or value not in allowed:
            raise ValidationError(f"{where} must be one of: {', '.join(allowed)}")
        return value
    if kind == "date":
        if not isinstance(value, str) or not _DATE_PATTERN.match(value):
            raise ValidationError(f"{where} must be a date such as 1980-04-12")
        try:
            date.fromisoformat(value)
        except ValueError as error:
            raise ValidationError(f"{where} is not a real calendar date") from error
        return value
    if kind == "instant":
        return _instant(value, where)
    if kind == "scalar":
        if isinstance(value, bool) or not isinstance(value, (int, float, str)):
            raise ValidationError(f"{where} must be a number or a string")
        return value
    return value


def _identifiers(value: Any, resource_type: str, field: str) -> list[str]:
    if not isinstance(value, list) or not value:
        raise ValidationError(f"{resource_type}.{field} must be a non-empty array of identifiers")
    entries: list[str] = []
    for index, item in enumerate(value):
        where = f"{resource_type}.{field}[{index}]"
        if not isinstance(item, dict):
            raise ValidationError(f"{where} must be an object")
        unknown = set(item) - {"system", "value"}
        if unknown:
            raise ValidationError(f"{where} has unknown fields: {', '.join(sorted(unknown))}")
        system = _string(item.get("system"), f"{where}.system")
        identifier = _string(item.get("value"), f"{where}.value")
        if "|" in system or "|" in identifier:
            raise ValidationError(f"{where} must not contain the '|' separator")
        entries.append(f"{system}|{identifier}")
    if len(entries) != len(set(entries)):
        raise ValidationError(f"{resource_type}.{field} must not contain duplicate identifiers")
    return entries


@dataclass(frozen=True)
class ValidatedResource:
    resource_type: str
    resource_id: str
    document: dict[str, Any]
    identifiers: tuple[str, ...]
    references: tuple[tuple[str, str], ...]


def parse_resource(resource_type: str, raw: Any, *, expected_id: str | None = None) -> ValidatedResource:
    """Validate a submitted resource body, ignoring the server-managed meta field."""
    if resource_type not in RESOURCE_TYPES:
        raise NotFoundError(f"resource type {resource_type} is not supported")
    if not isinstance(raw, dict):
        raise ValidationError("resource must be a JSON object")
    body_type = raw.get("resourceType")
    if body_type is not None and body_type != resource_type:
        raise ValidationError(f"resourceType must be {resource_type}")
    resource_id = _identifier(raw.get("id"), "resource id")
    if expected_id is not None and resource_id != expected_id:
        raise ValidationError(f"resource id {resource_id} does not match the request path id {expected_id}")
    allowed = set(_FIELDS[resource_type]) | {"resourceType", "id", "meta"}
    unknown = set(raw) - allowed
    if unknown:
        raise ValidationError(
            f"{resource_type} has unknown fields: {', '.join(sorted(unknown))}; "
            f"allowed fields are {', '.join(sorted(allowed))}"
        )

    document: dict[str, Any] = {}
    identifiers: list[str] = []
    references: list[tuple[str, str]] = []
    for field, (required, kind, _) in _FIELDS[resource_type].items():
        if field not in raw:
            if required:
                raise ValidationError(f"{resource_type}.{field} is required")
            continue

